import { component$ } from "@qwik.dev/core";
import {
  rubricGradeStampAsset,
  rubricGradeTier,
} from "../../utils/rubric-feedback";

interface GradeStampProps {
  grade: string;
  score: number;
  color: string;
  size?: "compact" | "report";
  animated?: boolean;
}

/** A complete grade-specific impression, recolored by the active theme. */
export const GradeStamp = component$<GradeStampProps>((props) => {
  const tier = rubricGradeTier(props.grade);
  const asset = rubricGradeStampAsset(props.grade);
  return (
    <div
      class={[
        "rubric-grade-stamp",
        `rubric-grade-stamp--${props.size ?? "compact"}`,
        `rubric-grade-stamp--${tier}`,
        { "rubric-grade-stamp--animated": props.animated },
      ]}
      style={{
        color: props.color,
        "--rubric-stamp-image": `url("${asset}")`,
      }}
      role="img"
      aria-label={`Overall grade ${props.grade}, ${props.score} of 100`}
    />
  );
});
export type RubricGradeTier = "a" | "b" | "c" | "revise";

export interface RubricSoundProfile {
  toneHz: number;
  toneDuration: number;
  impactGain: number;
}

const SOUND_PROFILES: Record<string, RubricSoundProfile> = {
  "A+": { toneHz: 784, toneDuration: 0.17, impactGain: 0.03 },
  A: { toneHz: 740, toneDuration: 0.16, impactGain: 0.031 },
  "A-": { toneHz: 698, toneDuration: 0.15, impactGain: 0.032 },
  "B+": { toneHz: 622, toneDuration: 0.15, impactGain: 0.033 },
  B: { toneHz: 587, toneDuration: 0.14, impactGain: 0.034 },
  "B-": { toneHz: 554, toneDuration: 0.14, impactGain: 0.035 },
  "C+": { toneHz: 494, toneDuration: 0.13, impactGain: 0.036 },
  C: { toneHz: 466, toneDuration: 0.12, impactGain: 0.037 },
  "C-": { toneHz: 440, toneDuration: 0.12, impactGain: 0.038 },
  "D+": { toneHz: 392, toneDuration: 0.11, impactGain: 0.039 },
  D: { toneHz: 370, toneDuration: 0.11, impactGain: 0.04 },
  "D-": { toneHz: 349, toneDuration: 0.1, impactGain: 0.041 },
  F: { toneHz: 294, toneDuration: 0.1, impactGain: 0.042 },
};

const GRADE_STAMP_ASSETS: Record<string, string> = {
  "A+": "/assets/rubric-stamps/a-plus.svg",
  A: "/assets/rubric-stamps/a.svg",
  "A-": "/assets/rubric-stamps/a-minus.svg",
  "B+": "/assets/rubric-stamps/b-plus.svg",
  B: "/assets/rubric-stamps/b.svg",
  "B-": "/assets/rubric-stamps/b-minus.svg",
  "C+": "/assets/rubric-stamps/c-plus.svg",
  C: "/assets/rubric-stamps/c.svg",
  "C-": "/assets/rubric-stamps/c-minus.svg",
  "D+": "/assets/rubric-stamps/d-plus.svg",
  D: "/assets/rubric-stamps/d.svg",
  "D-": "/assets/rubric-stamps/d-minus.svg",
  F: "/assets/rubric-stamps/f.svg",
};

let rubricAudioContext: AudioContext | null = null;

export function rubricGradeTier(grade: string): RubricGradeTier {
  const letter = grade.trim().toUpperCase().charAt(0);
  if (letter === "A") return "a";
  if (letter === "B") return "b";
  if (letter === "C") return "c";
  return "revise";
}

export function rubricSoundProfile(grade: string): RubricSoundProfile {
  return SOUND_PROFILES[grade.trim().toUpperCase()] ?? SOUND_PROFILES.F;
}

/** Each possible result has its own complete, transparent ink impression. */
export function rubricGradeStampAsset(grade: string): string {
  return GRADE_STAMP_ASSETS[grade.trim().toUpperCase()] ?? GRADE_STAMP_ASSETS.F;
}

function audioContextConstructor(): typeof AudioContext | null {
  if (typeof window === "undefined") return null;
  return (
    window.AudioContext ??
    (
      window as typeof window & {
        webkitAudioContext?: typeof AudioContext;
      }
    ).webkitAudioContext ??
    null
  );
}

/** Prime audio while the Run rubric click still owns a user gesture. */
export async function primeRubricFeedback(): Promise<boolean> {
  try {
    const AudioContextClass = audioContextConstructor();
    if (!AudioContextClass) return false;
    if (!rubricAudioContext || rubricAudioContext.state === "closed") {
      rubricAudioContext = new AudioContextClass();
    }
    if (rubricAudioContext.state === "suspended") {
      await rubricAudioContext.resume();
    }
    return rubricAudioContext.state === "running";
  } catch {
    rubricAudioContext = null;
    return false;
  }
}

function noiseBuffer(context: AudioContext, duration: number): AudioBuffer {
  const frames = Math.max(1, Math.floor(context.sampleRate * duration));
  const buffer = context.createBuffer(1, frames, context.sampleRate);
  const channel = buffer.getChannelData(0);
  for (let i = 0; i < frames; i += 1) {
    channel[i] = Math.random() * 2 - 1;
  }
  return buffer;
}

/** A tiny high-frequency shuffle, used as immediate feedback for sending. */
export function playRubricPaperCue(): void {
  try {
    const context = rubricAudioContext;
    if (!context || context.state !== "running") return;

    const now = context.currentTime;
    const source = context.createBufferSource();
    const filter = context.createBiquadFilter();
    const gain = context.createGain();
    source.buffer = noiseBuffer(context, 0.11);
    filter.type = "bandpass";
    filter.frequency.setValueAtTime(1750, now);
    filter.Q.setValueAtTime(0.7, now);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.linearRampToValueAtTime(0.018, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.11);
    source.connect(filter).connect(gain).connect(context.destination);
    source.start(now);
    source.stop(now + 0.12);
  } catch {
    // Optional feedback must never interrupt rubric analysis.
  }
}

/** A soft stamp impact plus a short pitch keyed to the resulting grade tier. */
export function playRubricGradeCue(grade: string): void {
  try {
    const context = rubricAudioContext;
    if (!context || context.state !== "running") return;

    const profile = rubricSoundProfile(grade);
    const now = context.currentTime;

    const impact = context.createBufferSource();
    const impactFilter = context.createBiquadFilter();
    const impactGain = context.createGain();
    impact.buffer = noiseBuffer(context, 0.075);
    impactFilter.type = "lowpass";
    impactFilter.frequency.setValueAtTime(620, now);
    impactGain.gain.setValueAtTime(profile.impactGain, now);
    impactGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.075);
    impact
      .connect(impactFilter)
      .connect(impactGain)
      .connect(context.destination);
    impact.start(now);
    impact.stop(now + 0.08);

    const tone = context.createOscillator();
    const toneGain = context.createGain();
    tone.type = "sine";
    tone.frequency.setValueAtTime(profile.toneHz, now + 0.025);
    toneGain.gain.setValueAtTime(0.0001, now);
    toneGain.gain.linearRampToValueAtTime(0.018, now + 0.035);
    toneGain.gain.exponentialRampToValueAtTime(
      0.0001,
      now + profile.toneDuration,
    );
    tone.connect(toneGain).connect(context.destination);
    tone.start(now + 0.02);
    tone.stop(now + profile.toneDuration + 0.02);
  } catch {
    // Optional feedback must never interrupt a completed grade.
  }
}
import { component$, type PropFunction } from "@qwik.dev/core";
import ImgApprovalStamp from "../../media/approval-stamp.svg?jsx";
import { renderMarkdown } from "../../utils/markdown";
import { SpeakButton } from "../ui/speak-button";
import type { SuggestionPopover } from "./editor-state";

interface SuggestionPanelProps {
  suggestion: SuggestionPopover | null;
  stampVisible: boolean;
  onClose$: PropFunction<() => void>;
  onStrike$: PropFunction<() => void>;
  onAccept$: PropFunction<() => void>;
}

/** The accept-or-strike decision surface for a persona's proposed rewrite. */
export const SuggestionPanel = component$<SuggestionPanelProps>((props) => {
  const suggestion = props.suggestion;

  return (
    <>
      {suggestion && (
        <div
          class="fixed inset-0 z-50 flex items-center justify-center p-6"
          style="background: rgba(20, 16, 10, 0.55);"
          role="dialog"
          aria-label={`Proposed edit from ${suggestion.author}`}
          onClick$={props.onClose$}
        >
          <div
            class="bg-[var(--color-paper)] border-2 w-full max-w-xl flex flex-col"
            style={{
              "border-color": suggestion.color,
              "border-radius": "4px",
              "box-shadow": "0 20px 50px rgba(0,0,0,0.35)",
            }}
            onClick$={(event) => event.stopPropagation()}
          >
            <div
              class="px-5 py-3 border-b flex items-baseline justify-between gap-3"
              style={{
                "border-color": "var(--color-paper-3)",
                background: "var(--color-paper-soft)",
              }}
            >
              <p
                class="text-[0.7rem] tracking-[0.14em] uppercase"
                style={{
                  fontFamily: "var(--font-typewriter)",
                  color: suggestion.color,
                }}
              >
                {suggestion.author} proposes
              </p>
              <div class="flex items-center gap-1.5 flex-shrink-0">
                <SpeakButton
                  compact
                  id={`suggestion-${suggestion.id}`}
                  text={suggestion.replacement}
                  author={suggestion.author}
                  label={suggestion.author}
                />
                <button
                  onClick$={props.onClose$}
                  class="text-[var(--color-ink-muted)] hover:text-[var(--color-ink)] text-base"
                  aria-label="Close"
                >
                  ✕
                </button>
              </div>
            </div>
            <div class="px-5 py-4 space-y-3">
              <p
                class="text-[0.85rem] leading-6 line-through text-[var(--color-ink-muted)]"
                style={{ fontFamily: "var(--font-serif)" }}
              >
                {suggestion.original}
              </p>
              <p
                data-speech-id={`suggestion-${suggestion.id}`}
                class="text-[0.95rem] leading-6 text-[var(--color-ink)]"
                style={{ fontFamily: "var(--font-serif)" }}
              >
                {suggestion.replacement}
              </p>
              {suggestion.rationale && (
                <div
                  class="comment-markdown text-[0.78rem] italic leading-5 text-[var(--color-ink-light)]"
                  style={{ fontFamily: "var(--font-serif)" }}
                  dangerouslySetInnerHTML={renderMarkdown(suggestion.rationale)}
                />
              )}
              <div class="pt-2 flex gap-2 justify-end">
                <button
                  onClick$={props.onStrike$}
                  disabled={suggestion.busy}
                  class="btn-paper text-xs"
                >
                  Strike
                </button>
                <button
                  onClick$={props.onAccept$}
                  disabled={suggestion.busy}
                  class="btn-press text-xs"
                >
                  {suggestion.busy ? "Stamping…" : "Accept & stamp"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {props.stampVisible && (
        <div class="approval-stamp-overlay" aria-hidden="true">
          <ImgApprovalStamp aria-hidden="true" width="220" height="220" />
        </div>
      )}
    </>
  );
});
import type { JSXOutput } from "@qwik.dev/core";
import type { DossierFilingState } from "../../utils/dossier-filing";

/**
 * The folio — the one frame both authoring surfaces are filed into.
 *
 * The form and the conversation used to be two different pages that happened
 * to share a colour palette: the form was a card floating on a `min-h-screen`
 * document that scrolled, the conversation was a full-bleed transcript with
 * page-wide chrome above it. Switching between them redrew everything, which
 * made a change of *surface* read like a change of *place*.
 *
 * Here they are the same object. One sheet, locked to the viewport, with the
 * route chrome filed into its top edge, the live dossier on the left leaf, and
 * whatever the writer is actually working in on the right. Because both
 * surfaces emit the identical frame in the identical position, switching them
 * only swaps the leaves — and the right leaf is keyed so the swap feeds in
 * like paper rather than blinking.
 *
 * This is deliberately an *inline* component (a plain function, not
 * `component$`) taking its three regions as JSX props rather than as slots.
 * Projected content that contains a component does not pick up prop changes
 * from the projecting parent — the live dossier froze on whichever field was
 * active when it first mounted. Rendering inline keeps the leaves inside the
 * caller's own reactivity, where they belong.
 */
interface DossierFolioProps {
  /**
   * Which surface is filling the right leaf. Keys the feed animation, so a
   * surface switch is a sheet change rather than a repaint.
   */
  surface: "form" | "conversational";
  /** The top bar, filed into the folio's edge. */
  chrome: JSXOutput;
  /** The left leaf: the brief as it currently stands. */
  dossier: JSXOutput;
  /** The right leaf: the question, or the transcript. */
  leaf: JSXOutput;
  /** Rendered outside the folio — transient overlays like the sending pip. */
  overlays?: JSXOutput;
  /** Persistence state, reflected by the paper outline and filing stamp. */
  filingState?: DossierFilingState;
}

export const DossierFolio = (props: DossierFolioProps) => {
  const filingState = props.filingState ?? "idle";
  return (
    <main class="flex h-[100dvh] min-h-0 flex-col overflow-hidden paper-sheet paper-foxed">
      {props.overlays}
      <div class="mx-auto flex min-h-0 w-full max-w-[92rem] flex-1 flex-col px-3 py-3 sm:px-5 sm:py-4">
        <div
          class="dossier-folio-frame folio relative flex min-h-0 flex-1 flex-col overflow-hidden"
          data-filing-state={filingState}
          aria-busy={filingState === "filing"}
        >
          {props.chrome}

          <div class="grid min-h-0 flex-1 overflow-hidden lg:grid-cols-[minmax(0,1fr)_minmax(0,1.02fr)]">
            {/* ── LEFT LEAF: the dossier as it stands ─────────────────── */}
            <div
              class="folio-column border-b border-[var(--color-paper-3)] px-5 py-4 lg:border-b-0 lg:border-r"
              style="background: linear-gradient(165deg, var(--color-paper-soft) 0%, var(--color-paper-2) 100%);"
            >
              {props.dossier}
            </div>

            {/* ── RIGHT LEAF: the surface the writer is working in ────── */}
            <div
              key={props.surface}
              class="folio-shift flex min-h-0 flex-col bg-[var(--color-paper)]"
            >
              {props.leaf}
            </div>
          </div>

          {filingState === "filed" && (
            <div
              class="dossier-filed-confirmation"
              role="status"
              aria-live="polite"
            >
              <div class="dossier-filed-confirmation__paper">
                <span
                  class="dossier-filed-confirmation__mark"
                  aria-hidden="true"
                >
                  ✓
                </span>
                <strong>Filed</strong>
                <span>Dossier saved to this folio</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </main>
  );
};

