// @exec: {"yield_time_ms": 1000, "max_output_tokens": 500}
await Promise.all(load("stampJobs").map(async ([name,label,color,shape])=>{
const prompt=`Use case: logo-brand. Asset type: transparent UI stamp for Twyne, a literary writing desk. Create one isolated ${shape}. Perfectly centered, upright, flat front view. Printed ${color} ink, tactile fine rubber-stamp distress, crisp legible bold editorial slab-serif typography, authentic engraved stationery craft. Exact text only: "${label}". Large central lettering; no other words. Transparent background with true alpha, no paper, no mockup, no shadow, no background glow. Entire stamp comfortably inside image with generous transparent margin. Square canvas. The sunburst is printed ink, not a 3D badge.`;
store("prompt-"+name,prompt);
const result=await tools.image_gen__imagegen({prompt});store("image-"+name,result);notify({name,resultMetadata: Object.fromEntries(Object.entries(result).filter(([k])=>!["image_url","content"].includes(k)))});}));

