  position: relative;
  z-index: 1;
}
.rubric-proof--fresh {
  animation: rubric-proof-settle 380ms cubic-bezier(0.16, 1, 0.3, 1) both;
  transform-origin: top center;
}

.rubric-grade-stamp {
  --stamp-rotation: -4deg;
  position: relative;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--color-ink);
  transform: rotate(var(--stamp-rotation));
  transform-origin: center;
  isolation: isolate;
}
.rubric-grade-stamp::before {
  position: absolute;
  inset: 0;
  background: currentColor;
  content: "";
  opacity: 0.82;
  -webkit-mask: var(--rubric-stamp-image) center / contain no-repeat;
  mask: var(--rubric-stamp-image) center / contain no-repeat;
  mix-blend-mode: multiply;
}
.rubric-grade-stamp--compact {
  width: 5rem;
  height: 3.45rem;
}
.rubric-grade-stamp--report {
  width: 8rem;
  height: 5.5rem;
}
.rubric-grade-stamp--a {
  --stamp-rotation: -5deg;
}
.rubric-grade-stamp--b {
  --stamp-rotation: 3deg;
}
.rubric-grade-stamp--c {
  --stamp-rotation: -2deg;
}
.rubric-grade-stamp--revise {
  --stamp-rotation: 4deg;
}
.rubric-grade-stamp--animated.rubric-grade-stamp--a {
  animation: rubric-stamp-a 340ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.rubric-grade-stamp--animated.rubric-grade-stamp--b {
  animation: rubric-stamp-b 340ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.rubric-grade-stamp--animated.rubric-grade-stamp--c {
  animation: rubric-stamp-c 350ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.rubric-grade-stamp--animated.rubric-grade-stamp--revise {
  animation: rubric-stamp-revise 360ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rubric-proof-settle {
  from {
    filter: contrast(0.96) brightness(1.025);
    transform: translateY(-4px) scaleY(0.992);
  }
  to {
    filter: contrast(1) brightness(1);
    transform: translateY(0) scaleY(1);
  }
}

@keyframes rubric-stamp-a {
  from {
    filter: blur(1.2px);
    opacity: 0.3;
    transform: translateY(-12px) rotate(-9deg) scale(1.14);
  }
  to {
    filter: blur(0);
    opacity: 1;
    transform: translateY(0) rotate(-5deg) scale(1);
  }
}

@keyframes rubric-stamp-b {
  from {
    filter: blur(1px);
    opacity: 0.32;
    transform: translateY(-10px) rotate(7deg) scale(1.12);
  }
  to {
    filter: blur(0);
    opacity: 1;
    transform: translateY(0) rotate(3deg) scale(1);
  }
}

@keyframes rubric-stamp-c {
  from {
    filter: blur(0.9px);
    opacity: 0.34;
    transform: translateY(-9px) rotate(-5deg) scale(1.1);
  }
  to {
    filter: blur(0);
    opacity: 1;
    transform: translateY(0) rotate(-2deg) scale(1);
  }
}

@keyframes rubric-stamp-revise {
  from {
    filter: blur(0.75px);
