const { chromium } = req("@playwright/test");
(async () => {
  const browser = await chromium.launch({headless:true, args:["--no-sandbox", "--enable-unsafe-swiftshader"]});
  const page = await browser.newPage({viewport:{width:1100,height:1000}});
  const errors = [];
  page.on("pageerror", e => errors.push(e.message));
  await page.goto("http://127.0.0.1:6006/iframe.html?id=rubric-sunburst-stamps--all-impressions&viewMode=story");
  await page.getByRole("button", {name:"Replay impressions"}).waitFor({timeout:60000});
  await page.getByRole("button", {name:"Replay impressions"}).click();
  await page.waitForTimeout(450);
  await page.screenshot({path:"/tmp/twyne-stamps-desktop.png",fullPage:true});
  console.log(JSON.stringify({errors, canvasCount:await page.locator("canvas").count(), body:(await page.locator("body").innerText()).slice(0,500)}));
  await page.emulateMedia({reducedMotion:"reduce"});
  await page.setViewportSize({width:390,height:844});
  await page.getByRole("button", {name:"Replay impressions"}).click();
  await page.screenshot({path:"/tmp/twyne-stamps-mobile.png",fullPage:true});
  console.log(JSON.stringify(await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth, visibleCanvases:[...document.querySelectorAll("canvas")].filter(c=>getComputedStyle(c).display!=="none").length}))));
  await browser.close();
})();

